$(document).ready(function(){$(window).scroll(function(){var scrollPosition=$(this).scrollTop();var opacity=1-scrollPosition*0.002;var translateY=scrollPosition*0.1;opacity=Math.max(0.1,opacity);translateY=Math.min(100,translateY);$('.hero .scroll-parallax').css({'opacity':opacity,'transform':'translateY('+translateY+'px)'});});});